from datetime import date
from collections import defaultdict


class Loyalty:
    def __init__(self) -> None:
        self._purchases = defaultdict(list)
        self._redemptions = defaultdict(list)

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount <= 0:
            raise ValueError("Purchase amount must be positive")

        points = int(amount // 10)
        self._purchases[customer].append((day, points))
        return points

    def balance(self, customer: str, day: date) -> int:
        earned = sum(
            points
            for purchase_day, points in self._purchases[customer]
            if (day - purchase_day).days >= 14
        )
        redeemed = sum(
            points
            for redemption_day, points in self._redemptions[customer]
            if redemption_day <= day
        )
        return earned - redeemed

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points < 0:
            raise ValueError("Points must be nonnegative")
        if points > self.balance(customer, day):
            raise ValueError("Insufficient points")
        self._redemptions[customer].append((day, points))
